import{_ as e,o as a,c as l,a2 as i}from"./chunks/framework.z3u3TMv0.js";const u=JSON.parse('{"title":"30-minute quickstart","description":"Zero to first local-model reply in MiniTavern — pick Ollama or LM Studio, pull a model, connect over LAN in about 30 minutes.","frontmatter":{"title":"30-minute quickstart","description":"Zero to first local-model reply in MiniTavern — pick Ollama or LM Studio, pull a model, connect over LAN in about 30 minutes.","head":[["meta",{"name":"keywords","content":"tavern,AI tavern,MiniTavern,AI companion,AI friend,AI local chat,Silly Tavern,SillyTavern,Silly Tavern mobile,Silly Tavern Android,Silly Tavern iOS,AI roleplay,character card,AI chat,mobile AI,offline AI,AI story,local LLM,Ollama,LM Studio,lorebook,regex,BYOK,user guide,docs,AI chat client"}],["meta",{"property":"og:title","content":"30-minute quickstart · MiniTavern Docs"}],["meta",{"property":"og:description","content":"Zero to first local-model reply in MiniTavern — pick Ollama or LM Studio, pull a model, connect over LAN in about 30 minutes."}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/en/quickstart"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/en/quickstart"}]]},"headers":[],"relativePath":"en/quickstart.md","filePath":"en/quickstart.md","lastUpdated":1787224147000}'),o={name:"en/quickstart.md"};function n(r,t,s,d,c,p){return a(),l("div",null,[...t[0]||(t[0]=[i('<h1 id="_30-minute-quickstart" tabindex="-1">30-minute quickstart <a class="header-anchor" href="#_30-minute-quickstart" aria-label="Permalink to &quot;30-minute quickstart&quot;">​</a></h1><p>Goal: from zero to your first local-model reply in MiniTavern.</p><table tabindex="0"><thead><tr><th>Step</th><th>~Time</th><th>What to do</th></tr></thead><tbody><tr><td>1</td><td>0–5 min</td><td>Pick a tool: Ollama or LM Studio</td></tr><tr><td>2</td><td>5–15 min</td><td>Install and download a small model</td></tr><tr><td>3</td><td>15–20 min</td><td>Enable LAN / Local Server</td></tr><tr><td>4</td><td>20–25 min</td><td>Find the PC’s LAN IP</td></tr><tr><td>5</td><td>25–30 min</td><td>Create a MiniTavern link and Test</td></tr></tbody></table><hr><h2 id="step-1-pick-a-tool" tabindex="-1">Step 1: Pick a tool <a class="header-anchor" href="#step-1-pick-a-tool" aria-label="Permalink to &quot;Step 1: Pick a tool&quot;">​</a></h2><ul><li><strong>Fastest</strong>: <a href="/ultra_guides/en/ollama/install">Ollama</a> or <a href="/ultra_guides/en/lmstudio/install">LM Studio</a></li><li><strong>Roleplay-oriented</strong>: later try <a href="/ultra_guides/en/koboldcpp/install">KoboldCPP</a></li><li><strong>Already have GGUF</strong>: <a href="/ultra_guides/en/llamacpp/install">llama.cpp</a></li></ul><p>Full comparison: <a href="/ultra_guides/en/local/tools">Tools overview</a>. Below uses <strong>Ollama</strong> as the path; for other tools, swap “pull model / start server” for that tool’s chapters — Step 5 is the same.</p><hr><h2 id="step-2-install-and-pull-a-small-model" tabindex="-1">Step 2: Install and pull a small model <a class="header-anchor" href="#step-2-install-and-pull-a-small-model" aria-label="Permalink to &quot;Step 2: Install and pull a small model&quot;">​</a></h2><ol><li>Install per <a href="/ultra_guides/en/ollama/install">Ollama install</a>.</li><li>In a terminal (small example model, good for verifying the path):</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ollama</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> llama3.2:3b</span></span></code></pre></div><ol start="3"><li>Confirm it works locally:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ollama</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> llama3.2:3b</span></span></code></pre></div><p>Chat once, then <code>/bye</code> to exit. More choices: <a href="/ultra_guides/en/ollama/models">Download and pick models</a>.</p><hr><h2 id="step-3-enable-lan-access" tabindex="-1">Step 3: Enable LAN access <a class="header-anchor" href="#step-3-enable-lan-access" aria-label="Permalink to &quot;Step 3: Enable LAN access&quot;">​</a></h2><p>Follow <a href="/ultra_guides/en/ollama/lan">Enable LAN access</a>: set <code>OLLAMA_HOST=0.0.0.0</code> and allow firewall port <strong>11434</strong>.</p><p>Then on the <strong>PC</strong>, open in a browser (any response is fine — not necessarily a pretty page):</p><p><code>http://127.0.0.1:11434</code></p><hr><h2 id="step-4-find-the-pc-lan-ip" tabindex="-1">Step 4: Find the PC LAN IP <a class="header-anchor" href="#step-4-find-the-pc-lan-ip" aria-label="Permalink to &quot;Step 4: Find the PC LAN IP&quot;">​</a></h2><ul><li><strong>Windows</strong>: <code>Win + R</code> → <code>cmd</code> → <code>ipconfig</code>, find <strong>IPv4 Address</strong> under the Wi‑Fi adapter (e.g. <code>192.168.x.x</code>).</li><li><strong>macOS</strong>: System Settings → Network → current Wi‑Fi → IP in details; or terminal <code>ipconfig getifaddr en0</code>.</li></ul><p>Write it down as <code>YOUR_PC_IP</code>.</p><hr><h2 id="step-5-configure-minitavern" tabindex="-1">Step 5: Configure MiniTavern <a class="header-anchor" href="#step-5-configure-minitavern" aria-label="Permalink to &quot;Step 5: Configure MiniTavern&quot;">​</a></h2><ol><li>Open the App → <strong>Settings → Models → Model link → New</strong>.</li><li>Platform: <strong>Custom (OpenAI)</strong> (exact label follows the App).</li><li>Fill in:</li></ol><table tabindex="0"><thead><tr><th>Field</th><th>Example (Ollama)</th></tr></thead><tbody><tr><td>Base URL</td><td><code>http://YOUR_PC_IP:11434/v1</code></td></tr><tr><td>API Key</td><td>Empty or any placeholder (local usually does not check)</td></tr><tr><td>Model name</td><td><code>llama3.2:3b</code> (same as <code>ollama list</code>)</td></tr></tbody></table><ol start="4"><li>Save and <strong>Test</strong>; on success set as default, import a character card, and chat.</li></ol><p>Full UI: <a href="/ultra_guides/en/connect-app/minitavern">Configure in MiniTavern</a>.</p><hr><h2 id="failed" tabindex="-1">Failed? <a class="header-anchor" href="#failed" aria-label="Permalink to &quot;Failed?&quot;">​</a></h2><ul><li>Test failed, timeout, empty reply → <a href="/ultra_guides/en/troubleshoot">Troubleshoot</a></li><li>Most common mistakes: <strong>Base URL set to <code>localhost</code></strong>, or phone and PC not on the same Wi‑Fi</li></ul>',32)])])}const m=e(o,[["render",n]]);export{u as __pageData,m as default};
